// 入力: { kind: 'members'|'pcs'|'servers'|'catalog', id?: string }
// 出力: 1件 = 1エンティティ { id, kind, desired, state, _meta }
//
// 台帳の格納先を知っているのはこのワークフローだけ(Repository パターン)。
// 呼び出し側は kind と id しか知らない。
// 設計: docs/design/03-service-catalog.md(台帳リポジトリ)

const input = $input.first()?.json ?? {};
const kind = input.kind;
const id = input.id ?? null;

// role ごとの読み取り先ディレクトリ(null は「その role は存在しない」)
const LAYOUT = {
  members: { desired: 'members', state: 'state/members' },
  pcs:     { desired: null,      state: 'state/pcs' },
  servers: { desired: null,      state: 'state/servers' },
  catalog: { desired: 'catalog', state: null },
};

if (!LAYOUT[kind]) {
  throw new Error(`ledger-read: 不正な kind: ${JSON.stringify(kind)}(有効値: ${Object.keys(LAYOUT).join(', ')})`);
}

const repo = $env.LEDGER_REPO;
if (!repo) throw new Error('ledger-read: LEDGER_REPO が未設定です');

const out = [];
for (const dir of Object.values(LAYOUT[kind])) {
  if (!dir) continue;
  out.push({ json: { kind, id, repo, dir, url: `https://api.github.com/repos/${repo}/contents/${dir}` } });
}
return out;

// HTTP Request ノードは JSON 配列の応答を自動で複数アイテムに分割する。
// したがって各入力アイテム = ディレクトリ内の1エントリ。
// state ディレクトリが無い(404)場合はエラーオブジェクトが入るので type で弾く。

const ctx = $('読み取り対象を決める').first().json;
const items = [];

for (const item of $input.all()) {
  const entry = item.json;
  if (!entry || entry.type !== 'file' || !String(entry.name ?? '').endsWith('.yaml')) continue;

  const entityId = entry.name.replace(/\.yaml$/, '');
  if (ctx.id && entityId !== ctx.id) continue;

  items.push({ json: {
    url: `https://api.github.com/repos/${ctx.repo}/contents/${entry.path}`,
  }});
}

return items;

// base64 を復号して YAML をパースし、desired と state を id で突き合わせる。
// 応答自身が path と sha を持つため、ノード間のインデックス対応に依存しない。
// _meta.<role>.sha は ledger-write の楽観的排他(競合検出)に使う。

const YAML = require('yaml');
const ctx = $('読み取り対象を決める').first().json;
const merged = new Map();

for (const item of $input.all()) {
  const res = item.json;
  const path = res.path;
  if (!path) throw new Error('ledger-read: 応答に path がありません');
  if (res.encoding && res.encoding !== 'base64') {
    throw new Error(`ledger-read: ${path} の encoding が想定外です: ${res.encoding}`);
  }

  const text = Buffer.from(res.content ?? '', 'base64').toString('utf8');
  let parsed;
  try {
    parsed = YAML.parse(text);
  } catch (e) {
    throw new Error(`ledger-read: ${path} の YAML 解析に失敗: ${e.message}`);
  }

  const role = path.startsWith('state/') ? 'state' : 'desired';
  const entityId = path.split('/').pop().replace(/\.yaml$/, '');

  if (!merged.has(entityId)) {
    merged.set(entityId, { id: entityId, kind: ctx.kind, desired: null, state: null, _meta: {} });
  }
  const rec = merged.get(entityId);
  rec[role] = parsed;
  rec._meta[role] = { path, sha: res.sha };
}

return [...merged.values()].map((json) => ({ json }));
